"""Complete Danish cooked mayonnaise, wine mayonnaise, fish and cabbage salad."""
import pathlib,json,sqlite3,copy
root=pathlib.Path(__file__).parent
out=root.parent.parent/'outputs/SavorShelf-Content-Repairs'
db=sqlite3.connect(out/'grouped-work.sqlite3')
rows=json.loads((out/'dressing-candidates.json').read_text(encoding='utf-8'))

records={r['sourceId']:r for r in json.loads((root/'content-overrides.json').read_text(encoding='utf-8'))}
aliases={r['id']:r for r in json.loads((root/'recipe-aliases.json').read_text(encoding='utf-8'))}
newids=[]
def src(n):return json.loads(db.execute('select record from recipes where id=?',(rows[n]['id'],)).fetchone()[0])
def I(k,a,u,n,s):return dict(key=k,amount=a,unit=u,name=n,substitution=s)
def oil(a):return I('oil',a,'ml','olive oil','Use the same volume of a mild sunflower or rapeseed oil.')
def vinegar(a,kind='white wine'):return I('vinegar',a,'ml',kind+' vinegar','Use the same volume of cider vinegar for a different flavor.')
def salt(a=.5):return I('salt',a,'tsp','fine salt','Reduce or omit to taste.')
def pepper(a=.25):return I('pepper',a,'tsp','ground black pepper','Use the same amount of ground white pepper, or omit.')
def parsley(a=1):return I('parsley',a,'tsp','fresh parsley, finely chopped','Use the same amount of finely chopped chives.')
def tk(k):return '{{'+k+'}}'
STORE='Use promptly, or cover and refrigerate at 4°C (40°F) or colder for up to 3 days. Whisk again before serving; oil and vinegar naturally separate. This is a fresh dressing, not a shelf-stable preserve.'
NOTE=' Spoon measures use the app’s modern 15 ml tablespoon and 5 ml teaspoon. Yields, missing quantities and preparation times are modern estimates, not recovered historical measurements. Not kitchen-tested. Scaling changes ingredient amounts, not preparation times.'
def add(n,title,y,t,desc,items,steps,notes):
 s=src(n);r=copy.deepcopy(s['recipe']);r.update(title=title,description=desc,category='Condiments',servings=y,yieldUnit='servings',minutes=t,totalMinutes=t,ingredients=items,steps=steps,sourceStatus='adapted',versionNote='Modern measured adaptation',updatedAt='2026-09-22T20:00:00Z',notes=notes+NOTE,source=s['recipe']['source']+' SavorShelf measured adaptation.');r.pop('variants',None);r['sourceAliases']=[]
 records[r['id']]=dict(sourceId=r['id'],bodySha256=s['bodySha256'],recipe=r);newids.append(r['id']);return r
def variant(r,id,label,items,steps):r.setdefault('variants',[]).append(dict(id=id,label=label,ingredients=items,steps=steps))
def yolks(a):return I('yolks',a,'','large pasteurized egg yolks','Use 18 g commercially pasteurized liquid egg yolk per yolk; do not substitute unpasteurized raw egg.')
def mustard(a):return I('mustard',a,'tsp','dry mustard powder','Use the same volume of prepared Dijon mustard for a milder flavor.')
def cayenne():return I('cayenne',.0625,'tsp','ground cayenne pepper','Omit for a mild mayonnaise.')
def lemon(a):return I('lemon',a,'ml','lemon juice','Use the same volume of lime juice for a different flavor.')
COLD='Transfer to a clean covered container and refrigerate immediately at 4°C (40°F) or colder. Use within 3 days, using a clean spoon each time. This is fresh homemade mayonnaise, not a shelf-stable preserve.'
def emulsion(keys):
 return ['Set a clean small bowl on a damp towel to steady it. Whisk '+', '.join(tk(k) for k in keys)+' until smooth.','Measure {{oil}} into a jug. Whisk continuously while adding it drop by drop at first. Once the mixture is thick and glossy, add the remaining measured oil in a very thin stream, whisking until fully incorporated. Stop pouring if oil pools on the surface and whisk until it blends in.','The finished mayonnaise should be smooth and creamy. If it separates, put 1 teaspoon cold drinking water in a clean bowl and whisk the separated mixture into it a few drops at a time; this small repair addition changes the yield slightly.',COLD]
def eggsource(r):r['source']+=' Raw-yolk handling uses commercially pasteurized egg: https://www.foodsafety.gov/people-at-risk .';return r
def eggs(a):return I('eggs',a,'','large eggs for hard boiling','Use large pasteurized shell eggs if preferred; cook until the yolks are firm.')
def water(a,k='water'):return I(k,a,'ml','drinking water','Use the same volume of drinking water, topping up to cover as directed.')
def boil():return ['Put {{eggs}} in a saucepan with {{water}}, adding more water only if needed to cover by about 2 cm. Bring to a boil, cover, remove from heat and stand for 12 minutes. Cool under cold running water, peel and cut open; the yolks must be firm throughout.']
END='Keep covered at 4°C (40°F) or colder until serving. Refrigerate leftovers within 2 hours and use within 2 days. Do not leave the platter at room temperature for more than 2 hours.'
REF=' Cooking endpoints: https://www.foodsafety.gov/food-safety-charts/safe-minimum-internal-temperatures . Variety meats: https://ask.fsis.usda.gov/article/What-are-the-recommended-cooking-times-for-veal .'
def finish(r):r['category']='Main dishes';r['source']+=REF;return eggsource(r)

r=add(35,'Forloren Mayonnaise — Danish Cooked Dressing',24,60,'A thick stock-and-butter dressing is enriched with cooked yolks, cooled, and finished with tarragon vinegar and a modest amount of oil.',[I('butter',60,'g','unsalted butter','Use the same weight of a block-style dairy-free butter alternative.'),I('flour',60,'g','plain flour','Use the same weight of a plain gluten-free flour blend suitable for sauces.'),I('stock',400,'ml','unsalted prepared chicken stock','Use the same volume of unsalted prepared vegetable stock.'),I('yolks',5,'','large egg yolks','Use 18 g pasteurized liquid egg yolk per yolk; the sauce is still cooked.'),salt(.5),pepper(.125),vinegar(30,'tarragon'),oil(60)], ['Melt {{butter}} in a saucepan over medium-low heat. Stir in {{flour}} and cook for 2 minutes, stirring, without browning. Gradually whisk in {{stock}} to make a smooth sauce. Bring to a gentle simmer and cook for 5 minutes, stirring frequently, until very thick.','Beat {{yolks}} in a heatproof bowl. Remove the pan from the heat. Gradually whisk a few spoonfuls of the hot sauce into the yolks, then return the mixture to the pan. Cook over low heat, stirring constantly, until the sauce reaches 71°C (160°F) throughout; do not let it boil or catch on the bottom.','Transfer to a shallow bowl. Set over a larger bowl of ice water and stir frequently for about 15–20 minutes until cold, keeping the ice water out of the sauce.','Gradually whisk {{oil}} into the cold sauce, followed by {{vinegar}}, {{salt}} and {{pepper}}. It should be thick and spoonable. Use with cooked chilled poultry, fish or vegetables.','Cover and refrigerate promptly at 4°C (40°F) or colder. Use within 3 days. Refrigerate within 2 hours of preparation, or within 1 hour above 32°C (90°F). This is a fresh cooked dressing, not a shelf-stable preserve.'], 'The original page reads Tres Gr (12 Kvint): 60 g butter, not the extracted 30 g. Both butter and flour are therefore 60 g. Four modern tablespoons supply 60 ml oil. The stock volume, acid, seasoning, yield and timing are supplied modern quantities. The original cooked-yolk liaison is expanded to a measured cooking endpoint and rapid cooling. Twenty-four small dressing portions are estimated.');r['source']+=REF

WINE_ITEMS=[eggs(1),water(750),yolks(1),oil(15),lemon(15),I('wine',10,'ml','dry white wine','Use the same volume of unsalted vegetable stock for an alcohol-free version with a different flavor.'),salt(.125)]
WINE_STEPS=boil()+['Separate the cooked yolk and push through a fine sieve into a clean bowl. Refrigerate the white for another dish. Beat in {{yolks}} and {{salt}} until smooth.','Gradually beat in {{oil}}, a few drops at a time. Slowly mix in {{lemon}} and {{wine}} until evenly blended. This source formula is yolk-rich and uses very little oil; it makes a soft coating rather than a large batch of high-oil mayonnaise.']
WINE_NOTE='The original allows two uncooked yolks or two cooked yolks and prefers one of each. The preferred mixed-yolk version is used here, with a commercially pasteurized uncooked yolk. The original explicitly gives one tablespoon of oil, standardized to 15 ml. Half a lemon becomes a supplied modern 15 ml juice; the unspecified white wine and salt are supplied working amounts. '
def wine_variants(r,offset=0):
 for kind in ['raw','cooked']:
  vi=[]
  for i in r['ingredients']:
   if kind=='raw' and i['key'] in ['eggs','water']:continue
   if kind=='cooked' and i['key']=='yolks':continue
   vi.append(dict(i,amount=2) if (kind=='raw' and i['key']=='yolks') or (kind=='cooked' and i['key']=='eggs') else copy.deepcopy(i))
  vs=copy.deepcopy(r['steps'])
  if kind=='raw':
   vs[offset:offset+2]=['Whisk {{yolks}} and {{salt}} in a clean bowl until smooth. Use commercially pasteurized yolks because this sauce is not cooked.']
  else:vs[offset+1]='Separate the cooked yolks and push through a fine sieve into a clean bowl. Refrigerate the whites for another dish. Beat the sieved yolks with {{salt}} until smooth.'
  variant(r,'two-'+kind+'-yolks','With two '+('pasteurized uncooked' if kind=='raw' else 'cooked')+' yolks',vi,vs)
 vi=copy.deepcopy(r['ingredients'])+[I('whitepepper',.0625,'tsp','ground white pepper','Omit for the plain source version.'),I('sugar',.125,'tsp','powdered white sugar','Omit for the plain source version.')];vs=copy.deepcopy(r['steps']);vs.insert(offset+3,'Stir {{whitepepper}} and {{sugar}} into the finished sauce until evenly distributed.');variant(r,'pepper-sugar','With white pepper and sugar',vi,vs)

r=add(39,'Ægte Majonaise — Danish Lemon-and-Wine Sauce',4,35,'A small yolk-rich sauce combines a sieved cooked yolk, a pasteurized yolk, lemon and white wine, with little oil.',copy.deepcopy(WINE_ITEMS),copy.deepcopy(WINE_STEPS)+['Serve in small portions with already-cooked chilled fish or vegetables.',COLD],WINE_NOTE+'Both all-uncooked and all-cooked yolk versions are retained, together with the optional white-pepper-and-sugar seasoning. Four small condiment servings are estimated; the uncooked-yolk variation takes about 15 minutes.');eggsource(r);wine_variants(r)

r=add(34,'Cold Fish with Danish Lemon-and-Wine Mayonnaise',2,80,'Chilled poached fish is coated with a small amount of lemon-and-white-wine mayonnaise made from cooked and pasteurized yolks.',[I('fish',300,'g','raw boneless skinless white fish fillets','Use the same weight of cod, hake or sea bass fillets; check carefully for bones.'),water(1000,'fishwater')]+copy.deepcopy(WINE_ITEMS),['Bring {{fishwater}} to a gentle simmer in a wide pan. Add {{fish}} and poach for about 8–12 minutes until the thickest part reaches 63°C (145°F) and the fish flakes easily. Lift out, drain and check for bones without breaking the pieces unnecessarily. Spread in a shallow container and refrigerate promptly, within 2 hours of cooking, until cold, about 45 minutes.']+copy.deepcopy(WINE_STEPS)+['Place the cold fish pieces on a platter and spoon the mayonnaise over them. Serve chilled.',END],WINE_NOTE+'The short fish entry refers to sauce 265; that sauce is supplied in full. Missing fish weight, poaching water, yield and cooking/cooling time are modern additions. The whole boneless pieces in the source mean intact serving pieces, not necessarily a whole fish.');finish(r);wine_variants(r,1)

r=add(36,'Hvidkaal-Salat — Chopped Cabbage with Mustard Mayonnaise',6,50,'Finely chopped raw cabbage is dressed with mustard mayonnaise and garnished with tender cooked carrot and shredded green lettuce.',[I('cabbage',600,'g','white cabbage, outer leaves and core removed, prepared weight','Use the same weight of green cabbage; texture differs.'),I('carrots',150,'g','carrots, peeled and cut into thick rounds','Use the same weight of yellow carrots.'),water(750,'carrotwater'),I('lettuce',50,'g','green lettuce leaves, washed and dried','Use the same weight of romaine leaves.'),yolks(2),oil(250),vinegar(30,'tarragon'),I('mustard',15,'ml','prepared smooth mustard','Use the same volume of Dijon mustard.'),salt(.5),I('whitepepper',.125,'tsp','ground white pepper','Use the same amount of black pepper; the appearance changes.')],['Put {{carrots}} in a small pan with {{carrotwater}}. Bring to a boil and simmer for 8–12 minutes until tender. Drain, spread in a shallow dish and refrigerate until cold, about 20 minutes, then chop coarsely.','Remove any remaining damaged leaves from {{cabbage}}, rinse and dry it, then chop finely. Thinly shred {{lettuce}} and reserve for garnish.','Whisk {{yolks}}, {{salt}} and {{mustard}} in a clean bowl. Gradually whisk in {{oil}}, starting drop by drop, then in a thin stream as the sauce thickens. Add {{vinegar}} in small additions while whisking, followed by {{whitepepper}}.','Fold the finely chopped cabbage into the mayonnaise until evenly coated. Mound in a serving bowl and garnish with the cold chopped carrots and shredded lettuce. Serve chilled.','Keep covered at 4°C (40°F) or colder. Refrigerate within 2 hours, or within 1 hour above 32°C (90°F), and use within 2 days. The cabbage releases liquid as it stands; stir before serving.'], 'The full original specifies raw chopped white cabbage, mustard mayonnaise, cooked chopped carrot and green lettuce. A small cabbage is standardized to 600 g prepared weight. The sauce uses the same book’s two-yolk/250 ml oil formula from recipe 243, with the mustard required by this salad. Vegetable, acid, mustard and seasoning amounts are modern working quantities. The sauce-only colorings and duck-egg option in the general mayonnaise reference are not required ingredients of this cabbage salad.');r['category']='Salads';eggsource(r)
vi=[dict(i,key='lemonacid',name='lemon juice',substitution='Use the tarragon-vinegar base recipe if preferred.') if i['key']=='vinegar' else copy.deepcopy(i) for i in r['ingredients']];vs=[s.replace('{{vinegar}}','{{lemonacid}}') for s in r['steps']];variant(r,'lemon','With lemon mustard mayonnaise',vi,vs);r['notes']+=' The general sauce’s lemon alternative is retained as a full named variation.'

assert len(newids)==4,len(newids)
(root/'content-overrides.json').write_text(json.dumps(list(records.values()),ensure_ascii=False,indent=2),encoding='utf-8')
for id in newids:db.execute('insert or replace into decisions values(?,?,?,?,?)',(id,records[id]['bodySha256'],'prepared-adaptation','Full original sauces and main or salad cooking completed, with measured variants','repair-batch-026.py'))
db.commit();print(json.dumps(dict(newAdaptations=len(newids),newMergedSources=0,totalOverrides=len(records),totalAliases=len(aliases))))

